    [DimMaterial_SK]            bigint NOT NULL,
    [Material_BK]               varchar(20) NOT NULL,
    [MaterialName]              varchar(150) NULL,
    [MaterialCategoryCode]      varchar(20) NULL,
    [MaterialSecondaryCategory] varchar(80) NULL,
    [AggregateMaterial_BK]      varchar(20) NULL,
    [AggregateMaterialName]     varchar(80) NULL,
    [MaterialsContained]        varchar(400) NULL,
    [InsertLoadStepID]          varchar(36) NOT NULL,
    [InsertTimestamp]           datetime2(6) NOT NULL,
    [LastUpdateLoadStepID]      varchar(36) NOT NULL,
    [LastUpdateTimestamp]       datetime2(6) NOT NULL
);
GO

